INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Creative-Commons-Lizenz dasselbe wie Public Domain?', 2, '[{"text": "Nein", "correct": true, "because": "CC hat Bedingungen, PD nicht"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Regelungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dieser Lizenz?', 3, '[{"text": "Nutzung erlauben", "correct": true, "because": "Fördert Teilen unter Bedingungen"}, {"text": "Kommerzielle Nutzung verbieten", "correct": false, "because": "Nicht immer"}, {"text": "Urheberrecht abschaffen", "correct": false, "because": "Regelt, nicht aufhebt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer CC-Lizenz?', 5, '[{"text": "Namensnennung", "correct": true, "because": "Urheber wird genannt"}, {"text": "Weitergabe unter gleichen Bedingungen", "correct": true, "because": "Schützt Lizenz"}, {"text": "Kostenpflicht", "correct": false, "because": "Kostenlos"}, {"text": "Exklusive Rechte", "correct": false, "because": "Fördert Teilen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CC erlaubt Bearbeitung. b) Sie verbietet jede Nutzung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht dem Zweck"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung dieser Lizenz?', 4, '[{"text": "Bedingungen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Urheberangabe", "correct": false, "because": "Oft Pflicht"}, {"text": "Farbe des Logos", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CC-Lizenzen kostenpflichtig sind?', 2, '[{"text": "Nein", "correct": true, "because": "Kostenlos verfügbar"}, {"text": "Ja", "correct": false, "because": "Keine Gebühren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingung ist oft enthalten?', 3, '[{"text": "Namensnennung", "correct": true, "because": "Schützt den Urheber"}, {"text": "Verkaufsverbot", "correct": false, "because": "Nicht immer"}, {"text": "Exklusivität", "correct": false, "because": "Gegen Teilen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Freiheiten bietet eine CC-Lizenz?', 5, '[{"text": "Teilen", "correct": true, "because": "Kernprinzip"}, {"text": "Bearbeiten", "correct": true, "because": "Oft erlaubt"}, {"text": "Exklusive Nutzung", "correct": false, "because": "Nicht exklusiv"}, {"text": "Versteckte Nutzung", "correct": false, "because": "Fördert Offenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CC-Lizenzen sind flexibel. b) Sie verbieten kommerzielle Nutzung immer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommerzielle Nutzung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine CC-Lizenz?', 4, '[{"text": "Urheberangabe", "correct": false, "because": "Häufig erforderlich"}, {"text": "Lizenztext", "correct": false, "because": "Definiert Bedingungen"}, {"text": "Zahlung", "correct": true, "because": "Kostenfrei"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt CC nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Bilder, Musik etc."}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Varianten gibt es?', 4, '[{"text": "CC BY", "correct": true, "because": "Namensnennung"}, {"text": "CC NC", "correct": true, "because": "Nicht-kommerziell"}, {"text": "CC EX", "correct": false, "because": "Gibt es nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass CC das Urheberrecht aufhebt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Regelt Nutzung, hebt nicht auf"}, {"text": "Ja", "correct": false, "because": "Urheber bleibt geschützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl?', 3, '[{"text": "Nutzungsbedingungen", "correct": true, "because": "Passend zum Projekt"}, {"text": "Schnelle Anwendung", "correct": false, "because": "Rechtliche Klarheit zählt"}, {"text": "Kosten", "correct": false, "because": "Kostenlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CC fördert Teilen. b) Es ist nur national gültig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "International anerkannt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen kann es geben?', 5, '[{"text": "Nicht-kommerziell", "correct": true, "because": "Verbietet Verkauf"}, {"text": "Keine Bearbeitung", "correct": true, "because": "Schützt Original"}, {"text": "Kostenpflicht", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Lizenzbedingungen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Urheber", "correct": false, "because": "Muss genannt werden"}, {"text": "Schriftart", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich eine CC-Lizenz ändern?', 3, '[{"text": "Nein", "correct": true, "because": "Festgelegte Bedingungen"}, {"text": "Ja", "correct": false, "because": "Standardisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CC für Firmen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Nein", "correct": false, "because": "Auch kommerziell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Namensnennung?', 4, '[{"text": "Urheber ehren", "correct": true, "because": "Anerkennung geben"}, {"text": "Nutzung verbieten", "correct": false, "because": "Fördert Nutzung"}, {"text": "Kosten erhöhen", "correct": false, "because": "Kostenfrei"}]');
